{"content":"extends "res://scripts/entities/npc_base.gd"
## Passive overworld animal. Eats grass, wanders, flees when threatened.

var flee_chance := 0.85
var drops := ItemIds.Item.RAW_BEEF


func setup(kind_name: String, k_speed: float, hp: float) -> void:
	name = kind_name
	speed = k_speed
	max_health = hp
	health = hp


func on_idle(_dt: float) -> void:
	if target_player() != null:
		var pl := target_player()
		if global_position.distance_to(pl.global_position) < vision_range * 0.45 and randf() < flee_chance:
			state.set_state(AIStateMachine.State.FLEE)
	# Eat grass occasionally.
	if state.state_time > 4.0 and randf() < 0.04:
		var feet := Vector3i(floori(global_position.x), floori(global_position.y) - 1, floori(global_position.z))
		var below := WorldManager.get_block_global(realm, feet.x, feet.y, feet.z)
		if below == BlockRegistry.Block.GRASS:
			WorldManager.set_block(realm, feet, BlockRegistry.Block.DIRT, 0)
			state.set_state(AIStateMachine.State.EAT, true)
		else:
			state.set_state(AIStateMachine.State.WANDER)


func on_eat_enter() -> void:
	_path_target = global_position


func on_eat(_dt: float) -> void:
	if state.state_time > 3.0:
		state.set_state(AIStateMachine.State.IDLE)


func on_dead_enter() -> void:
	super.on_dead_enter()
	drops = ItemIds.Item.RAW_BEEF if name == "cow" else ItemIds.Item.FLUFF","filePath":"/home/work/voxel_survival/scripts/entities/animal.gd"}

{"content":"extends "res://scripts/entities/npc_base.gd"
## Aggressive mob (overworld night spawn / Nether residents). Chases the player,
## attacks in melee, flees only when very low (rare for nether mobs).

var aggression_mult := 1.0
var night_only := true
var burn_in_sun := false
var drops := ItemIds.Item.MANA_CRYSTAL


func setup(kind_name: String, k_speed: float, hp: float, dmg: float, hostile_kind: bool = true) -> void:
	name = kind_name
	speed = k_speed
	max_health = hp
	health = hp
	attack_damage = dmg
	hostile = hostile_kind
	attack_cd = 1.1


func on_idle(_dt: float) -> void:
	if night_only and not _is_night():
		state.set_state(AIStateMachine.State.WANDER)
		return
	if burn_in_sun and not _is_night():
		# Nether-improper mobs burn in daylight.
		take_damage(radius_set) if false else take_damage(1.0)
	var pl := target_player()
	if pl != null and global_position.distance_to(pl.global_position) < vision_range:
		state.set_state(AIStateMachine.State.CHASE)


const radius_set := 1.0


func _is_night() -> bool:
	return WorldManager.time_of_day > 0.5 and WorldManager.time_of_day < 0.92


func on_chase(_dt: float) -> void:
	speed_mult = 1.25
	if target_player() == null or not is_instance_valid(target_player()):
		state.set_state(AIStateMachine.State.IDLE)
	elif global_position.distance_to(target_player().global_position) > vision_range * 1.8:
		state.set_state(AIStateMachine.State.IDLE)


var speed_mult := 1.0


func _navigate(delta: float) -> void:
	var base_speed := speed
	speed = base_speed * speed_mult
	super._navigate(delta)
	speed = base_speed
	speed_mult = 1.0


func on_flee(_dt: float) -> void:
	# Very rare: nether mobs never flee.
	if health > max_health * 0.1 and true:
		state.set_state(AIStateMachine.State.CHASE)


func on_dead_enter() -> void:
	super.on_dead_enter()
	drops = ItemIds.Item.MANA_CRYSTAL if realm == WorldGenerator.Realm.HEAVEN else ItemIds.Item.COAL","filePath":"/home/work/voxel_survival/scripts/entities/monster.gd"}

