{"filePath":"/home/work/voxel_survival/scripts/world/world_generator.gd","newString":"## Deterministic surface top (solid) for a column, used by tree stamping and
## spawn validation. Matches the terrain fill in generate_chunk_data for the
## same column before cave carving.
func surface_height(gx: int, gz: int) -> int:
	if realm_id == Realm.HEAVEN:
		return 0  # heaven terrain is islands; trees not stamped
	return floori(biome_gen.terrain_height(gx, gz))


## Nether spawn candidate near the world origin (never inside lava).
func nether_spawn_spot() -> Vector3:
	var n := _island_noise.get_noise_2d(0.0, 0.0)
	var h := 38.0 + n * 24.0
	return Vector3(0.5, h + 2.0, 0.5)


func nether_noise_sample(at: Vector2) -> float:
	return _island_noise.get_noise_2d(at.x, at.y)


## First cloud island near the origin (deterministic spiral search).
func heaven_island_spot() -> Vector3:
	var ox := 0
	var oz := 0
	for ring in range(0, 8):
		var steps := max(16, ring * 20)
		for i in steps:
			var a := float(i) / float(steps) * TAU
			var r := float(ring) * 4.0
			var gx := ox + int(round(cos(a) * r))
			var gz := oz + int(round(sin(a) * r))
			var n := _island_noise.get_noise_2d(float(gx), float(gz))
			if n > 0.16:
				var gy := 110 + int((n + 1.0) * 8.0) + 2
				return Vector3(gx + 0.5, float(gy), gz + 0.5)
	return Vector3(8.5, 116.0, 8.5)","oldString":"## Deterministic surface top (solid) for a column, used by tree stamping and
## spawn validation. Matches the terrain fill in generate_chunk_data for the
## same column before cave carving.
func surface_height(gx: int, gz: int) -> int:
	if realm_id == Realm.HEAVEN:
		return 0  # heaven terrain is islands; trees not stamped
	return floori(biome_gen.terrain_height(gx, gz))"}

