## Main scene controller: spawns the single-player local pawn when offline,
## hands the rest to NetworkManager when online.

var spawned := false


func _ready() -> void:
	if not NetworkManager.is_online():
		_spawn_singleplayer()


func _spawn_singleplayer() -> void:
	# Wait until WorldManager has chosen a valid spawn.
	await get_tree().process_frame
	await get_tree().process_frame
	if spawn_position_setup_done:
		return
	spawn_position_setup_done = true
	var scene: PackedScene = load("res://scenes/player/player.tscn")
	var player := scene.instantiate()
	player.name = "Player_1"
	player.peer_id = 1
	player.is_local = true
	player.creative = ProjectSettings.get_setting("application/config/creative_mode", false)
	player.global_position = WorldManager.spawn_position
	var players: Node = get_node_or_null("Players")
	players.add_child(player)
	NetworkManager.seed_player(player, 1)
	WorldManager.show_hud()


var spawn_position_setup_done := false


func _process(_delta: float) -> void:
	if not spawned and get_node_or_null("Players") != null \
			and get_node_or_null("Players").get_child_count() > 0:
		spawned = true","filePath":"/home/work/voxel_survival/scripts/main/main.gd"}

{"content":"extends Node
## Simple realm environment driver: adjusts WorldEnvironment sky/fog when the
## active realm changes. Declaration-only for now - the Environment resource can
## be swapped here without any Editor interaction.
##
## Hooked into WorldManager.set_active_realm() via the "world_env" group.

@onready var env: WorldEnvironment = get_node_or_null("Env")


func apply_realm(realm: int) -> void:
	if env == null:
		return
	var e: Environment = env.environment
	if e == null:
		return
	var meta := WorldManager.REALMS.get(realm, WorldManager.REALMS[WorldGenerator.Realm.OVERWORLD])
	e.clear_color = meta.sky
	e.fog_enabled = true
	e.fog_density = 1.0 / maxf(meta.fog_dist, 1.0)
	e.fog_light_color = meta.sky
	e.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	e.ambient_light_color = meta.sky * 0.6
	e.ambient_light_energy = 1.0
	if realm == WorldGenerator.Realm.NETHER:
		e.ambient_light_energy = 0.45","filePath":"/home/work/voxel_survival/scripts/main/world_env.gd"}

