{"content":"class_name TestCase
extends RefCounted
## Minimal assertion harness for headless GDScript tests.

var _name := "test"
var _failures := 0
var _checks := 0


func setup() -> void:
	pass


func check(cond: bool, msg: String) -> void:
	_checks += 1
	if not cond:
		_failures += 1
		printerr("   [FAIL] %s" % msg)


func eq(a: Variant, b: Variant, msg: String) -> void:
	_checks += 1
	if a != b:
		_failures += 1
		printerr("   [FAIL] %s (expected %s, got %s)" % [msg, str(b), str(a)])


func near(a: float, b: float, tol: float, msg: String) -> void:
	_checks += 1
	if absf(a - b) > tol:
		_failures += 1
		printerr("   [FAIL] %s (expected %.4f, got %.4f)" % [msg, b, a])


func finish(suite: String) -> int:
	print("[RESULT] %s: %d checks, %d failures" % [suite, _checks, _failures])
	return _failures","filePath":"/home/work/voxel_survival/tests/test_case.gd"}

{"content":"extends TestCase
## Crafting atomicity + forge (manual & electric) energy/stamina correctness.

func run() -> int:
	setup()
	_craft_tests()
	_forge_manual_tests()
	_forge_electric_tests()
	return finish("test_crafting")


func _craft_tests() -> void:
	var inv := Inventory.new(40, 9)
	inv.add_item(ItemIds.Item.OAK_LOG, 3)
	var recipe: Dictionary = RecipeDB.get_recipe("planks")
	check(not recipe.is_empty(), "planks recipe exists")
	var station := CraftingManager.STATION_FORGE
	# Without enough energy for smelt recipes, craft is rejected.
	var r_smelt: Dictionary = RecipeDB.get_recipe("smelt_copper")
	inv.add_item(ItemIds.Item.RAW_COPPER, 1)
	check(not CraftingManager.can_craft(inv, r_smelt, station, 0.0), "smelt blocked without heat energy")
	check(not CraftingManager.craft(inv, r_smelt, station, 0.0), "smelt craft aborted")
	eq(inv.count_item(ItemIds.Item.RAW_COPPER), 1, "ore untouched by aborted smelt")
	check(CraftingManager.craft(inv, r_smelt, station, 500.0), "smelt with heat succeeds")
	eq(inv.count_item(ItemIds.Item.RAW_COPPER), 0, "ore consumed")
	eq(inv.count_item(ItemIds.Item.INGOT_COPPER), 1, "copper ingot produced")
	# Exact craft: 1 log -> 4 planks, nothing extra.
	check(CraftingManager.craft(inv, recipe, station, 0.0), "plank craft ok")
	eq(inv.count_item(ItemIds.Item.OAK_LOG), 2, "one log consumed")
	eq(inv.count_item(ItemIds.Item.PLANKS), 4, "four planks produced")
	# Insufficient inputs: nothing happens.
	var r_sword: Dictionary = RecipeDB.get_recipe("sword_wood")
	var before := inv.serialize()
	check(not CraftingManager.craft(inv, r_sword, station, 0.0), "no crafting without materials")
	eq(inv.serialize(), before, "inventory unchanged on failed craft")


func _forge_manual_tests() -> void:
	var forge := Forge.new(Forge.Type.MANUAL, Vector3i(5, 40, 5))
	forge.add_fuel(ItemIds.Item.COAL, 4)
	# Heat the blank to forging temperature with several coals.
	for i in 10:
		forge._tick_temperature(1.0)
	eq_forge_hot(forge, true)
	var inv := Inventory.new(40, 9)
	inv.add_item(ItemIds.Item.HAMMER, 1)
	inv.add_item(ItemIds.Item.INGOT_IRON, 2)
	var recipe: Dictionary = RecipeDB.get_recipe("blank_iron")
	# Hammer the blank - stamina (hunger) is required; hungry blacksmith can't.
	var result := forge.forge_recipe(CraftingManager.STATION_FORGE, inv, 50.0,
		func(a): _track_stamina(a))
	check(result.ok, "manual forging works with stamina")
	eq(inv.count_item(ItemIds.Item.INGOT_IRON), 1, "one ingot consumed by manual forge")
	eq(inv.count_item(ItemIds.Item.BLANK_IRON), 1, "iron blank produced")
	# No stamina => tired.
	inv.add_item(ItemIds.Item.INGOT_IRON, 1)
	var tired := forge.forge_recipe(CraftingManager.STATION_FORGE, inv, 1.0,
		func(a): _track_stamina(a))
	check(not tired.ok and tired.reason == "tired", "exhausted smith cannot forge")
	eq(inv.count_item(ItemIds.Item.INGOT_IRON), 1, "ingot kept when too tired")


var _stamina_spent := 0.0


func _track_stamina(a: float) -> void:
	_stamina_spent += a


func eq_forge_hot(forge: Forge, want: bool) -> void:
	check((forge.temperature_c > 800.0) == want, "forge temperature reachable (~%.0f C)" % forge.temperature_c)


func _forge_electric_tests() -> void:
	var net := EnergyNetwork.new()
	var gen := EnergyNode.make(EnergyNode.Kind.GENERATOR_FUEL, Vector3i(0, 0, 0))
	gen.fuel.add_item(ItemIds.Item.COAL, 3)
	net.add_node(gen)
	var cable := EnergyNode.make(EnergyNode.Kind.CABLE, Vector3i(1, 0, 0))
	net.add_node(cable)
	var forge_node := EnergyNode.make(EnergyNode.Kind.CONSUMER, Vector3i(2, 0, 0))
	forge_node.demand_w = 200.0
	net.add_node(forge_node)
	var battery := EnergyNode.make(EnergyNode.Kind.STORAGE_BATTERY, Vector3i(3, 0, 0))
	battery.add_stored_energy(500.0)
	net.add_node(battery)
	var forge := Forge.new(Forge.Type.ELECTRIC, Vector3i(2, 0, 0))
	forge.network = net
	# Heat the electric forge via grid; the battery takes the heat cost.
	for i in 40:
		forge.electric_heat_step(0.25)
		net.tick(0.25)
	var inv := Inventory.new(40, 9)
	inv.add_item(ItemIds.Item.BLANK_IRON, 1)
	inv.add_item(ItemIds.Item.STICK, 1)
	var recipe: Dictionary = RecipeDB.get_recipe("sword_iron")
	var result := forge.forge_recipe(CraftingManager.STATION_ELECTRIC_FORGE, inv, 100.0, func(a): pass)
	check(result.ok, "electric forge produces sword with stored power")
	eq(inv.count_item(ItemIds.Item.SWORD_IRON), 1, "sword produced")
	# Without stored energy an exact-energy recipe is refused (conservation).
	var inv2 := Inventory.new(40, 9)
	inv2.add_item(ItemIds.Item.BLANK_IRON, 1)
	inv2.add_item(ItemIds.Item.STICK, 1)
	battery.charge_kj = 0.0
	var result2 := forge.forge_recipe(CraftingManager.STATION_ELECTRIC_FORGE, inv2, 100.0, func(a): pass)
	check(not result2.ok, "no energy -> no forging (conservation enforced)")","filePath":"/home/work/voxel_survival/tests/test_crafting.gd"}

