{"content":"extends TestCase
## World generation invariants:
##   - no opposite-temperature biomes adjacent (snow<->desert wall)
##   - no floating physical clusters after the structural validator
##   - no fully-sealed (unreachable) resource nodes
##   - spawn point satisfies flatness/water/resources rules

func run() -> int:
	setup()
	var gen: WorldGenerator = WorldManager.generator_for(WorldGenerator.Realm.OVERWORLD)
	_biome_adjacency(gen)
	_no_floating_before_and_after(gen)
	_cut_ore_removed(gen)
	_spawn_rules(gen)
	return finish("test_worldgen")


func _biome_adjacency(gen: WorldGenerator) -> void:
	var bg := gen.biome_gen
	var bad := 0
	var checked := 0
	for cx in range(-24, 25):
		for cz in range(-24, 25):
			var p := Vector2i(cx * ChunkData.CHUNK_X + 8, cz * ChunkData.CHUNK_Z + 8)
			var a := bg.get_biome_id(p.x, p.y)
			for d in [Vector2i(16, 0), Vector2i(0, 16)]:
				var q := p + d
				var b := bg.get_biome_id(q.x, q.y)
				checked += 1
				if (a == BiomeGenerator.Bio.SNOW and b == BiomeGenerator.Bio.DESERT) \
						or (a == BiomeGenerator.Bio.DESERT and b == BiomeGenerator.Bio.SNOW):
					bad += 1
	check(bad == 0, "no snow<->desert adjacency across %d sampled pairs" % checked)
	check(checked > 1000, "biome adjacency sample is meaningful")


func _no_floating_before_and_after(gen: WorldGenerator) -> void:
	var validator := WorldValidator.new()
	var gravel_count := 0
	var stone_count := 0
	for cx in range(-2, 3):
		for cz in range(-2, 3):
			var chunk := gen.generate_chunk_data(cx, cz)
			var stats := validator.validate_support(chunk)
			gravel_count += stats.gravity_flagged.size()
			stone_count += stats.removed.size()
			validator.validate_no_cut_ores(chunk)
			# Everything still unsupported after validation must be gravity-only.
			var unsupported := 0
			for lx in ChunkData.CHUNK_X:
				for lz in ChunkData.CHUNK_Z:
					var grounded := false
					for y in ChunkData.CHUNK_Y:
						var id := chunk.get_block(lx, y, lz)
						if y <= 1:
							grounded = id != BlockRegistry.Block.AIR and BlockRegistry.is_collidable(id)
							continue
						if id == BlockRegistry.Block.AIR or BlockRegistry.is_fluid(id) or not BlockRegistry.is_solid(id):
							grounded = false
							continue
						if BlockRegistry.is_float_island(id):
							grounded = true
							continue
						if grounded:
							grounded = true
						elif BlockRegistry.is_gravity(id):
							pass
						else:
							unsupported += 1
			check(unsupported == 0, "no unsupported solids left in chunk (%d,%d)" % [cx, cz])
	check(stone_count >= 0, "validator ran")
	check(gravel_count >= 0, "validator handles sand/gravel as falling blocks")


func _cut_ore_removed(gen: WorldGenerator) -> void:
	var chunk := ChunkData.new(Vector2i(0, 0), WorldGenerator.Realm.OVERWORLD)
	# A resource fully sealed by unbreakable blocks is a cut node.
	chunk.set_block(8, 40, 8, BlockRegistry.Block.ORE_IRON)
	for n in [
		Vector3i(9, 40, 8), Vector3i(7, 40, 8), Vector3i(8, 41, 8),
		Vector3i(8, 39, 8), Vector3i(8, 40, 9), Vector3i(8, 40, 7),
	]:
		chunk.set_block(n.x, n.y, n.z, BlockRegistry.Block.BEDROCK)
	# A reachable ore next to breakable stone stays.
	chunk.set_block(3, 40, 3, BlockRegistry.Block.ORE_COAL)
	chunk.set_block(4, 40, 3, BlockRegistry.Block.STONE)
	var validator := WorldValidator.new()
	var cut := validator.validate_no_cut_ores(chunk)
	eq(chunk.get_block(8, 40, 8), BlockRegistry.Block.STONE, "sealed ore converted to stone")
	check(cut.size() >= 1, "cut ore was reported")
	eq(chunk.get_block(3, 40, 3), BlockRegistry.Block.ORE_COAL, "reachable ore preserved")


func _spawn_rules(gen: WorldGenerator) -> void:
	var sv := SpawnValidator.new(gen)
	var spot := sv.find_spawn()
	check(spot != Vector3.ZERO, "spawn found")
	# Flatness rule re-check on the chosen spot.
	var h := gen.surface_height(spot.x, spot.z)
	check(h >= BiomeGenerator.SEA_LEVEL + 2, "spawn not in the ocean")
	var min_h := h
	var max_h := h
	for dx in range(-2, 3):
		for dz in range(-2, 3):
			min_h = mini(min_h, gen.surface_height(spot.x + dx, spot.z + dz))
			max_h = maxi(max_h, gen.surface_height(spot.x + dx, spot.z + dz))
	check(max_h - min_h <= 3, "spawn area is flat (variance %d)" % (max_h - min_h))
	check(sv._water_near(spot.x, spot.z, 32), "water within 32 blocks of spawn")","filePath":"/home/work/voxel_survival/tests/test_worldgen.gd"}

